<script lang="ts">
 import { onMount, tick } from 'svelte'
 import Dialog from './lib/Dialog.svelte'
 import VoiceVisual from './lib/VoiceVisual.svelte'
 import * as api from './lib/api'
 import { inspectCapture } from './lib/audio-check'
 import { Recorder, DuplexRecorder,LiveRecorder, Speaker, referenceWAV } from './lib/audio'
 type Turn = {id:number;input:string;reply:string;language:string;phase:string;state:'running'|'complete'|'canceled'|'error';metrics?:api.Event}
 let server= $state<api.Status|null>(null), connected=$state(false), error=$state(''),busy=$state(false),recording=$state(false),starting=$state(false),saving=$state(false),canceling=$state(false),playing=$state(false),seconds=$state(0),draft=$state(''),turns=$state<Turn[]>([]),mode=$state('dark')
 let nextID=0,disposed=false,cancelRequested=false,pollTimer:ReturnType<typeof setTimeout>,recordTimer:ReturnType<typeof setInterval>|undefined,stopTimer:ReturnType<typeof setTimeout>|undefined,controller:AbortController|undefined
 let confirmReference=$state(false),notice=$state('')
 let settingsTab=$state('voice'),confirmAction=$state<'prompt'|'new'|null>(null),confirmNative=$state(false),pendingNative=$state(false),modelProblem=$state(''),clock=$state(Date.now()),followTranscript=$state(true)
 let skin=$state('cloud'),customPrompt=$state(''),promptID=$state(''),promptEditing=$state(false),modelCatalog=$state<api.ModelCatalog|null>(null),selectedProfile=$state(''),selectedModel=$state(''),modelsLoading=$state(false)
 let animationOverride=$state<boolean|null>(null), systemMotion=$state(true)
 const motionEnabled=$derived(animationOverride??systemMotion)
 function setMotion(enabled:boolean){animationOverride=enabled;try{localStorage.setItem('veyra-animation',String(enabled))}catch{}}
 let duplexActive=$state(false),duplexStarting=$state(false),duplexToken='',duplexSequence=0,duplexController:AbortController|undefined,duplexQueue:ArrayBuffer[]=[],duplexSending=false
 let live=$state(false), liveStarting=$state(false), liveSpeaking=$state(false), cooldownUntil=0
 let referenceRecording=$state(false), settingsOpen=$state(false), transcriptOpen=$state(false), micLevel=$state(0), outputLevel=$state(0)
 const recorder=new Recorder(value=>micLevel=value),speaker=new Speaker(value=>{if(playing&&!value)cooldownUntil=Date.now()+450;playing=value},value=>outputLevel=value)
 const liveRecorder=new LiveRecorder(()=>live&&!liveStarting&&!busy&&!playing&&!saving&&!starting&&connected&&server?.state==='ready'&&Date.now()>cooldownUntil,wav=>{if(live&&!busy)void send('turn',wav,'Voice message')},value=>micLevel=value,value=>liveSpeaking=value,()=>{error='Microphone disconnected. Start Live again after reconnecting it.';void stopLive()})
 const duplexRecorder=new DuplexRecorder(wav=>{if(duplexActive){duplexQueue.push(wav);if(duplexQueue.length>3){error="Model cannot keep up with microphone audio.";void stopDuplex()}else void drainDuplex()}},value=>micLevel=value,()=>{error="Microphone disconnected.";void stopDuplex()})

 let microphoneID=$state(''), microphones=$state<MediaDeviceInfo[]>([]),micTesting=$state(false),micSample=$state(''),micSummary=$state('')

 const voiceState=$derived(modelsLoading?'Loading model':micTesting?'Testing microphone':duplexStarting?"Starting duplex":duplexActive?playing?"Speaking & listening":"Listening":recording?'Listening':playing?'Speaking':busy?'Thinking':starting?'Starting':saving?'Updating':!connected?'Connecting':server?.state==='error'?'Needs attention':server?.state==='loading'?'Loading model':liveStarting?'Starting Live':live?'Listening':'Ready')

 const level=$derived(micTesting?micLevel:duplexActive?Math.max(micLevel,outputLevel):recording||live&&!busy&&!playing?micLevel:playing?outputLevel:0)

 const selectedBackend=$derived(modelCatalog?.profiles.find(item=>item.id===selectedProfile))
 const nativeSelected=$derived(selectedBackend?.mode==='minicpm-native')
 const modelsDirty=$derived(!!modelCatalog&&(selectedProfile!==modelCatalog.profile||(!nativeSelected&&selectedModel!==modelCatalog.model)))
 const promptDirty=$derived(promptEditing&&(promptID!==(server?.preferences.prompt??'')||customPrompt!==(server?.preferences.custom_prompt??'')))
 const loadingSeconds=$derived(server?.startup?.started_at?Math.max(0,Math.floor((clock-Date.parse(server.startup.started_at))/1000)):0)
 const available=$derived(!modelsLoading&&!micTesting&&connected&&server?.state==='ready'&&!busy&&!saving&&!starting&&!canceling)

 const locked=$derived(modelsLoading||micTesting||duplexActive||duplexStarting||live||liveStarting||busy||recording||starting||saving||canceling||server?.state==='loading'||!connected)

 const languageItems=$derived([...(server?.capabilities.automatic_language?[{value:'auto',label:'Follow my speech'}]:[]),...(server?.capabilities.languages??[]).map(value=>({value,label:value==='en'?'English':value==='ru'?'Russian':value}))])

 const voiceItems=(language:string)=>(server?.capabilities.voices??[]).filter(v=>v.language===language).map(v=>({value:v.id,label:v.name}))

 const voiceValue=(language:string)=>server?.preferences.voices?.[language]??server?.capabilities.voices?.find(v=>v.language===language&&v.default)?.id??null

 function describe(e:unknown){return e instanceof Error?e.message:String(e)}

 async function poll(){try{const current=await api.status();if(disposed)return;if(server?.state==='loading'&&current.state!=='loading'){void api.models().then(value=>{modelCatalog=value;if(current.state==='ready'){selectedProfile=value.profile;selectedModel=value.model}}).catch(()=>{});if(current.state==='ready'&&pendingNative){turns=[];draft=''}pendingNative=false}server=current;connected=true;if(!promptEditing){customPrompt=current.preferences.custom_prompt??'';promptID=current.preferences.prompt??''}}catch{if(!disposed)connected=false}finally{if(!disposed)pollTimer=setTimeout(poll,1000)}}

 onMount(()=>{const wallClock=setInterval(()=>clock=Date.now(),1000);const media=matchMedia('(prefers-reduced-motion: reduce)');const motion=()=>systemMotion=!media.matches;motion();media.addEventListener('change',motion);try{const stored=localStorage.getItem('veyra-animation');if(stored!==null)animationOverride=stored==='true';mode=localStorage.getItem('veyra-mode')??'dark'}catch{};try{microphoneID=localStorage.getItem('veyra-microphone')??''}catch{};try{const saved=localStorage.getItem('veyra-skin');if(saved&&['cloud','lens','scanner'].includes(saved))skin=saved}catch{};void refreshMicrophones();void poll();return()=>{clearInterval(wallClock);media.removeEventListener('change',motion);disposed=true;clearTimeout(micTestTimer);if(micSample)URL.revokeObjectURL(micSample);void micTester.dispose();clearTimeout(pollTimer);clearInterval(recordTimer);clearTimeout(stopTimer);controller?.abort();void duplexRecorder.dispose();duplexController?.abort();void liveRecorder.dispose();void recorder.dispose();void speaker.dispose()}})



 async function choosePrompt(){if(!promptID||locked)return;if((turns.length||server?.has_history)&&confirmAction!=='prompt'){confirmAction='prompt';return}confirmAction=null;saving=true;error='';speaker.mute();try{await api.command('prompt',{id:promptID,custom:customPrompt});turns=[];promptEditing=false;server=await api.status()}catch(e){error=describe(e)}finally{saving=false}}
 function chooseSkin(value:string){skin=value;try{localStorage.setItem('veyra-skin',value)}catch{}}
 async function openSettings(){if(live)await stopLive();if(duplexActive)await stopDuplex();confirmReference=false;settingsTab=server?.state==='error'||server?.state==='loading'?'models':'voice';settingsOpen=true;modelProblem='';try{modelCatalog=await api.models();selectedProfile=modelCatalog.profile;selectedModel=modelCatalog.models.some(item=>item.id===modelCatalog!.model)?modelCatalog.model:modelCatalog.models[0]?.id??'';confirmNative=false}catch(e){modelProblem=describe(e)}}
 async function applyModels(){if(locked||modelsLoading||!selectedBackend||selectedBackend.unavailable||nativeSelected&&!confirmNative||selectedBackend.requires_new&&!confirmNative)return;modelsLoading=true;modelProblem='';speaker.mute();try{await api.command('models',{profile:selectedProfile,model:nativeSelected?'':selectedModel,new_conversation:!!selectedBackend.requires_new&&confirmNative});pendingNative=!!selectedBackend.requires_new;server=await api.status()}catch(e){modelProblem=describe(e)}finally{modelsLoading=false}}
 function closeSettings(){settingsOpen=false;confirmAction=null;if(micTesting)void finishMicrophoneTest();if(referenceRecording)void discardRecording()}
 async function discardRecording(){recording=false;referenceRecording=false;stopClock();await recorder.dispose();notice='Recording discarded.'}
 async function restoreSetup(){if(!modelCatalog)return;selectedProfile=modelCatalog.profile;selectedModel=modelCatalog.model;confirmNative=true;await applyModels()}
 async function cancelLoading(){try{await api.command('models/cancel')}catch(e){modelProblem=describe(e)}}
 function changeBackend(){confirmNative=false;modelProblem=''}
 function discardPrompt(){customPrompt=server?.preferences.custom_prompt??'';promptID=server?.preferences.prompt??'';promptEditing=false;confirmAction=null}
 function newConversation(){if(turns.length||server?.has_history){confirmAction='new';return}void reset()}
 function showConversation(){followTranscript=true;transcriptOpen=true}
 let transcriptBody:HTMLDivElement
 $effect(()=>{const content=turns.map(turn=>turn.reply).join('');if(content&&transcriptOpen&&followTranscript&&transcriptBody){void tick().then(()=>{if(transcriptBody)transcriptBody.scrollTop=transcriptBody.scrollHeight})}})
 async function activate(){if(busy){await cancel();return}if(playing){speaker.mute();return}if(server?.state==='error'){await openSettings();return}if(server?.capabilities.full_duplex){if(duplexActive)await stopDuplex();else await startDuplex();return}if(live){await stopLive();return}await record()}
 async function drainDuplex(){if(duplexSending)return;duplexSending=true;try{while(duplexActive&&duplexQueue.length&&duplexController){const wav=duplexQueue.shift()!;await api.duplexChunk(duplexToken,duplexSequence++,wav,duplexController.signal)}}catch(e){if(duplexActive){error=describe(e);await stopDuplex()}}finally{duplexSending=false}}
 async function startDuplex(){if(!available||duplexActive||duplexStarting)return;duplexStarting=true;error='';duplexController=new AbortController();duplexQueue=[];duplexSequence=0
 try{await speaker.ready();await api.duplex(duplexController.signal,async event=>{
  if(event.token){duplexToken=event.token;await duplexRecorder.start({deviceId:microphoneID});duplexActive=true;duplexStarting=false;turns=[]}
  if(event.text){if(!turns.length)turns=[{id:++nextID,input:'Continuous voice conversation',reply:'',language:'en',phase:'',state:'running'}];turns=turns.map((t,i)=>i===turns.length-1?{...t,reply:t.reply+event.text}:t)}
  if(event.audio&&duplexActive)await speaker.enqueue(event.audio)
 })}catch(e){if(duplexActive||duplexStarting)error=describe(e)}finally{duplexActive=false;duplexStarting=false;await duplexRecorder.dispose();speaker.mute();duplexController=undefined;duplexQueue=[];duplexToken='';try{server=await api.status()}catch{connected=false}}
 }
 async function stopDuplex(){duplexActive=false;duplexStarting=false;await duplexRecorder.dispose();speaker.mute();if(duplexToken)await api.duplexStop(duplexToken).catch(()=>{});duplexController?.abort()}
 $effect(()=>{if(duplexActive&&(!connected||server?.state==='error'))void stopDuplex()})
 async function startLive(){if(!available||recording||live||liveStarting)return;liveStarting=true;error='';try{await speaker.ready();await liveRecorder.start({deviceId:microphoneID});if(disposed){await liveRecorder.dispose();return};live=true}catch(e){error=describe(e);await liveRecorder.dispose()}finally{liveStarting=false}}
 async function stopLive(){live=false;cooldownUntil=Date.now()+400;await liveRecorder.dispose();liveSpeaking=false;speaker.mute()}
 $effect(()=>{if(live&&(!connected||server?.state==='error'))void stopLive()})
 function theme(){mode=mode==='light'?'dark':'light';try{localStorage.setItem('veyra-mode',mode)}catch{}}
 async function preferences(update:Partial<api.Preferences>){if(!server||locked)return;saving=true;error='';try{await api.command('preferences',{...server.preferences,...update});server=await api.status()}catch(e){error=describe(e)}finally{saving=false}}
 async function chooseVoice(language:string,value:string|null){if(value&&server)await preferences({voices:{...server.preferences.voices,[language]:value}})}
 function stopClock(){clearInterval(recordTimer);clearTimeout(stopTimer);recordTimer=undefined;stopTimer=undefined}
 async function record(reference=false){notice='';if(recording){await finish();return};if(!available||live||liveStarting)return;starting=true;error='';try{await speaker.ready();await recorder.start({deviceId:microphoneID});if(disposed){await recorder.dispose();return};referenceRecording=reference;recording=true;seconds=0;recordTimer=setInterval(()=>seconds++,1000);stopTimer=setTimeout(()=>void finish(),30000)}catch(e){error=describe(e)}finally{starting=false}}
 async function finish(){if(!recording)return;const reference=referenceRecording;recording=false;referenceRecording=false;stopClock();starting=true;try{const data=await recorder.stop();starting=false;if(!disposed){if(reference){if(data.byteLength<96044)throw Error('Record at least 3 seconds of clean speech.');await setReference(data)}else await send('turn',data,'Voice message')}}catch(e){error=describe(e)}finally{starting=false}}
 async function setReference(data?:ArrayBuffer){saving=true;error='';speaker.mute();try{await api.reference(data);turns=[];server=await api.status()}catch(e){error=describe(e);try{server=await api.status()}catch{connected=false}}finally{saving=false}}
 async function uploadReference(event:Event){const input=event.currentTarget as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||locked)return;saving=true;try{const data=await referenceWAV(file);await setReference(data)}catch(e){error=describe(e)}finally{saving=false}}
 async function send(path:'text'|'turn',input:string|ArrayBuffer,label:string){if(busy||disposed)return;liveSpeaking=false;busy=true;cancelRequested=false;error='';controller=new AbortController();const id=++nextID;turns=[...turns,{id,input:label,reply:'',language:'',phase:path==='turn'?'Listening':'Thinking',state:'running'}]
 const update=(change:Partial<Turn>)=>turns=turns.map(t=>t.id===id?{...t,...change}:t)
 try{await speaker.ready();await api.turn(path,input,controller.signal,async ev=>{if(disposed||controller?.signal.aborted)return;if(ev.transcript)update({input:ev.transcript,language:ev.language??''});if(ev.text){const existing=turns.find(t=>t.id===id)!;update({reply:existing.reply+ev.text,language:ev.language??existing.language})};if(ev.phase)update({phase:ev.phase==='prefill'?'Listening':'Thinking'});if(ev.audio){update({phase:'Speaking'});try{await speaker.enqueue(ev.audio)}catch(e){error='Playback: '+describe(e)}};if(ev.done)update({state:'complete',phase:'',metrics:ev})})}catch(e){if(live)await stopLive();if(cancelRequested||controller.signal.aborted)update({state:'canceled',phase:''});else{update({state:'error',phase:''});error=describe(e)}}finally{cooldownUntil=Date.now()+450;busy=false;controller=undefined;try{server=await api.status()}catch{connected=false}}}
 async function submit(){const text=draft.trim();if(!text||!available||recording||live)return;if(text.length>4000){error='Keep messages under 4,000 characters.';return};draft='';await send('text',text,text)}
 async function cancel(){if(live)await stopLive();cancelRequested=true;canceling=true;const pending=controller;speaker.mute();try{await api.command('cancel')}catch(e){error=describe(e)}finally{pending?.abort();canceling=false}}
 async function reset(){if(locked)return;saving=true;error='';speaker.mute();try{await api.command('reset');turns=[];draft='';server=await api.status()}catch(e){error=describe(e)}finally{saving=false}}

 let micTestTimer:ReturnType<typeof setTimeout>|undefined
 const micTester=new Recorder(value=>micLevel=value)
 async function refreshMicrophones(){try{microphones=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='audioinput')}catch(e){error=describe(e)}}
 function chooseMicrophone(id:string|null){if(locked||id===null)return;microphoneID=id==='default'?'':id;try{localStorage.setItem('veyra-microphone',microphoneID)}catch{};micSummary='';if(micSample){URL.revokeObjectURL(micSample);micSample=''}}
 async function testMicrophone(){if(micTesting){await finishMicrophoneTest();return};if(locked)return;micTesting=true;error='';speaker.mute();try{await micTester.start({deviceId:microphoneID});if(disposed){await micTester.dispose();return};await refreshMicrophones();micTestTimer=setTimeout(()=>void finishMicrophoneTest(),8000)}catch(e){micTesting=false;error=describe(e)}}
 async function finishMicrophoneTest(){clearTimeout(micTestTimer);try{const wav=await micTester.stop();if(disposed)return;const info=inspectCapture(wav),settings=micTester.settings;if(micSample)URL.revokeObjectURL(micSample);micSample=URL.createObjectURL(new Blob([wav],{type:'audio/wav'}));micSummary=`${info.seconds.toFixed(1)} s · ${Number.isFinite(info.rmsDb)?info.rmsDb.toFixed(0):'silent'} dBFS · ${info.clippedPercent.toFixed(2)}% clipped · source ${settings?.sampleRate??'unknown'} Hz → 16 kHz mono. ${info.peak<.01?'Input is very quiet; check the device and microphone level.':info.clippedPercent>1?'Input is clipping; lower the microphone gain.':'Play this back: your whole phrase should be clear.'}`}catch(e){error=describe(e)}finally{micTesting=false;micLevel=0}}
 const profile=$derived(server?.capabilities.profile??'Connecting…')
</script>
<svelte:window onkeydown={e=>{if(e.key==='Escape'&&!settingsOpen&&!transcriptOpen){if(recording)void discardRecording();else if(busy)void cancel();else if(playing)speaker.mute()}if(e.code==='Space'&&e.target===document.body){e.preventDefault();void activate()}}}/>
<div class="application" data-mode={mode}>
 <header><span class="wordmark">Veyra</span><button class="icon-button" onclick={openSettings} disabled={recording||starting} aria-label="Settings" title="Settings"><svg viewBox="0 0 24 24"><path d="m9.5 3-.6 2.1-2 .9-2-.5L2.4 10l1.5 1.6v2L2.4 15l2.5 4.4 2-.5 2 .9.6 2.2h5l.6-2.2 2-.9 2 .5 2.5-4.4-1.5-1.4v-2l1.5-1.6L19.1 5.5l-2 .5-2-.9L14.5 3Z"/><circle cx="12" cy="12.5" r="3.2"/></svg></button></header>
 <main class="device">
  <button class="orb voice-orb" data-state={voiceState.toLowerCase()} aria-label={server?.state==='error'?'Open recovery settings':busy?'Cancel response':playing?'Stop speaking':duplexActive?'Stop full duplex':server?.capabilities.full_duplex?'Start full duplex':live?'Stop Live':recording?'Stop & send':'Record a message'} disabled={canceling||duplexStarting||liveStarting||referenceRecording||starting||saving||(!busy&&!playing&&!duplexActive&&!live&&!recording&&!available&&server?.state!=='error')} onclick={activate}><VoiceVisual {skin} {level} animate={motionEnabled} phase={voiceState}/></button>
  <h1 class="state" aria-live="polite">{voiceState}</h1>
  <p class="hint">{server?.state==='error'?'Open Settings to choose a setup and retry.':duplexActive?'Listening while replying. Click to end.':live?busy||playing?'Listening pauses during replies.':liveSpeaking?'Hearing you. Pause to send.':'Speak freely. Click to end.':recording?`Click to send · ${seconds}s / 30s`:busy?'Click to cancel':playing?'Click to stop playback':available?'Click to speak':server?.state==='loading'?'Loading models. Conversation stays in place.':'Connecting to Veyra…'}</p>
  {#if recording&&!referenceRecording}<button class="quiet" onclick={discardRecording}>Discard recording</button>{/if}{#if notice}<p class="field-note" role="status">{notice}</p>{/if}
  {#if server?.state==='loading'}<div class="startup-status" role="status"><span class="spinner"></span><span>{server.startup?.stage||'Preparing models'}</span><span>{loadingSeconds}s</span></div><button class="quiet" onclick={cancelLoading}>Cancel loading</button>{/if}
  {#if error}<div class="inline-error" role="alert"><p>{error}</p><button class="quiet" onclick={()=>error=''}>Dismiss</button></div>{/if}
  {#if server?.state==='error'}<div class="recovery-card"><p>{server.detail}</p><button class="small-button primary" onclick={openSettings}>Choose a setup</button></div>{/if}
 </main>
 <footer class="device-footer"><button class="quiet" onclick={showConversation} disabled={recording||starting}>Conversation{turns.length?` · ${turns.length}`:''}</button><label class="handsfree">Hands-free<input type="checkbox" role="switch" checked={live||duplexActive} disabled={!live&&!duplexActive&&(!available||recording)} onchange={()=>server?.capabilities.full_duplex?duplexActive?stopDuplex():startDuplex():live?stopLive():startLive()}/></label></footer>
 <Dialog open={settingsOpen} title="Settings" onclose={closeSettings}>
  {#snippet navigation()}{#each [{id:'voice',name:'Voice'},{id:'conversation',name:'Conversation'},{id:'appearance',name:'Appearance'},{id:'models',name:'Models'}] as tab}<button class:active={settingsTab===tab.id} aria-current={settingsTab===tab.id?'page':undefined} onclick={()=>{settingsTab=tab.id;confirmAction=null}}>{tab.name}</button>{/each}{/snippet}
  {#if settingsTab==='voice'}
   <section class="settings-section"><h3>Microphone</h3><p class="section-description">Choose your input, then check it without sending a message.</p>
    <label class="field">Input device<select value={microphoneID||'default'} onchange={e=>chooseMicrophone(e.currentTarget.value)} disabled={locked}><option value="default">Windows default</option>{#each microphones.filter(d=>d.deviceId!=='default'&&d.deviceId!=='communications') as device,i}<option value={device.deviceId}>{device.label||`Microphone ${i+1}`}</option>{/each}</select></label>
    <button class="small-button" disabled={!micTesting&&locked} onclick={testMicrophone}>{micTesting?'Stop microphone test':'Test microphone'}</button>
    {#if micTesting}<p class="field-note" role="status">Speak a phrase · up to 8 seconds. Nothing is sent to a model.</p>{/if}
    {#if micSample}<audio controls src={micSample} aria-label="Microphone test playback"></audio><a class="text-link" href={micSample} download="veyra-microphone.wav">Save test recording</a><p class="field-note">{micSummary}</p>{/if}
   </section>
   <section class="settings-section"><h3>Speech</h3>
    {#if (server?.capabilities.voices.length??0)<=1}<div class="setting-value"><span>Voice</span><span>{server?.capabilities.voices[0]?.name??'Backend default'}</span></div>{/if}
    {#each server?.capabilities.languages??[] as language}{#if voiceItems(language).length>1}<label class="field">{language==='en'?'English voice':'Russian voice'}<select value={voiceValue(language)??''} onchange={e=>chooseVoice(language,e.currentTarget.value)} disabled={locked}>{#each voiceItems(language) as voice}<option value={voice.value}>{voice.label}</option>{/each}</select></label>{/if}{/each}
    {#if (server?.capabilities.languages.length??0)>1}<label class="field">Reply language<select value={server?.preferences.reply??''} onchange={e=>preferences({reply:e.currentTarget.value})} disabled={locked}>{#each languageItems as item}<option value={item.value}>{item.label}</option>{/each}</select></label>{/if}
    <p class="field-note">Use headphones. Hands-free pauses listening during replies.</p>
    {#if server?.capabilities.reference_conditioning}<details><summary>Reference voice · experimental</summary><p class="field-note">Use 3–30 seconds of clean speech. Changing the reference starts a new conversation.</p><label class="confirmation check"><input type="checkbox" bind:checked={confirmReference} disabled={locked}/><span>Start a new conversation when changing the reference.</span></label><button class="small-button" disabled={!referenceRecording&&(locked||!confirmReference)} onclick={()=>record(true)}>{referenceRecording?'Stop & use reference':'Record reference voice'}</button><label class="field">Reference audio<input type="file" accept="audio/*" disabled={locked||!confirmReference} onchange={uploadReference}/></label></details>{/if}
   </section>
  {:else if settingsTab==='conversation'}
   <section class="settings-section"><h3>How Veyra responds</h3><p class="section-description">Choose a preset or write your own instructions.</p>
    <label class="field">System prompt<select bind:value={promptID} onchange={()=>promptEditing=true} disabled={locked}>{#each server?.prompts??[] as prompt}<option value={prompt.id}>{prompt.name}</option>{/each}</select></label>
    <label class="field">Custom prompt<textarea rows="8" maxlength="4096" placeholder="Optional. Overrides the selected preset." bind:value={customPrompt} oninput={()=>promptEditing=true} disabled={locked}></textarea></label>
    <p class="field-note">{customPrompt.trim()?'Your custom instructions override the preset.':'The selected preset is active.'} Applying a change starts a new conversation.</p>
    {#if confirmAction==='prompt'}<div class="confirmation" role="alert"><h4>Start a new conversation?</h4><p>The new prompt applies to a fresh conversation. Your saved conversation stays available.</p><div class="button-row"><button class="small-button" onclick={()=>confirmAction=null}>Keep current conversation</button><button class="small-button primary" onclick={choosePrompt}>Apply and start new</button></div></div>{/if}
   </section>
  {:else if settingsTab==='appearance'}
   <section class="settings-section"><h3>Appearance</h3><label class="field">Theme<select value={mode} onchange={e=>{mode=e.currentTarget.value;try{localStorage.setItem('veyra-mode',mode)}catch{}}}><option value="dark">Dark</option><option value="light">Light</option></select></label><label class="field">Visual<select value={skin} onchange={e=>chooseSkin(e.currentTarget.value)}><option value="cloud">Cloud</option><option value="lens">Lens · HAL-inspired</option><option value="scanner">Scanner · KITT-inspired</option></select></label><p class="field-note">Only the visual changes. Your voice and models stay the same.</p><label class="switch-row"><span><strong>Animation</strong><small>Follows reduced motion unless you change it here.</small></span><input type="checkbox" role="switch" checked={motionEnabled} onchange={e=>setMotion(e.currentTarget.checked)}/></label></section>
  {:else}
   <section class="settings-section"><h3>Voice setup</h3>{#if busy||playing}<p class="field-note">Finish or stop the current reply before changing models.</p>{/if}<p class="section-description">Select the voice backend and a compatible conversation model.</p>
    {#if recording&&!referenceRecording}<button class="quiet" onclick={discardRecording}>Discard recording</button>{/if}{#if notice}<p class="field-note" role="status">{notice}</p>{/if}
  {#if server?.state==='loading'}<div class="loading-card" role="status"><div class="startup-status"><span class="spinner"></span><strong>{server.startup?.stage||'Loading models'}</strong><span>{loadingSeconds}s</span></div><p>Loading can be canceled. You can keep this window open.</p></div>{/if}
    {#if server?.state==='error'||modelProblem}<div class="inline-error" role="alert"><h4>Setup unavailable</h4><p>{modelProblem||server?.detail}</p>{#if server?.error_details||server?.startup?.log_dir}<details><summary>Technical details</summary><p>{server.error_details}</p><code>{server.startup?.log_dir}</code></details>{/if}</div>{/if}
    <label class="field">Voice backend<select bind:value={selectedProfile} onchange={changeBackend} disabled={locked||modelsLoading}>{#each modelCatalog?.profiles??[] as item}<option value={item.id} disabled={!!item.unavailable}>{item.name}{item.experimental?' · experimental':''}{item.unavailable?' · unavailable':''}</option>{/each}</select></label>
    {#if selectedBackend?.unavailable}<p class="field-note">{selectedBackend.unavailable}</p>{/if}
    {#if nativeSelected}<div class="backend-note"><strong>MiniCPM handles the whole conversation</strong><p>Recognition, reasoning and speech use its matching model bundle. No separate generation model is needed.</p><p class="field-note">Experimental: speech quality and recovery depend on the installed native runtime.</p></div>
    {:else}<label class="field">Generation model<select bind:value={selectedModel} disabled={locked||modelsLoading||!modelCatalog?.models.length}>{#if !modelCatalog?.models.length}<option value="">No compatible chat models found</option>{/if}{#each modelCatalog?.models??[] as item}<option value={item.id}>{item.name}</option>{/each}</select></label><p class="field-note">Only text chat models are listed. Audio encoders, speech decoders and projectors are excluded.</p>{/if}
    {#if selectedBackend?.requires_new}<label class="confirmation check"><input type="checkbox" bind:checked={confirmNative} disabled={locked}/><span>Start a new conversation with this backend.<small>Native audio context cannot be carried between backends.</small></span></label>{:else}<p class="field-note">Your conversation stays in place. The current models unload before the selection starts.</p>{/if}
    <p class="field-note">Changes last until Veyra closes.</p>
   </section>
  {/if}
  {#snippet footer()}<span class="footer-note">{settingsTab==='conversation'&&promptDirty?'Unsaved prompt':settingsTab==='models'&&server?.state==='loading'?'Loading models…':' '}</span><div class="button-row">{#if settingsTab==='models'&&server?.state==='loading'}<button class="small-button" onclick={cancelLoading}>Cancel loading</button>{:else if settingsTab==='models'}{#if server?.state==='error'&&modelCatalog?.can_restore}<button class="small-button" onclick={restoreSetup} disabled={locked||modelsLoading}>Restore previous setup</button>{/if}<button class="small-button primary" onclick={applyModels} disabled={locked||modelsLoading||!selectedBackend||!!selectedBackend.unavailable||(!nativeSelected&&!selectedModel)||!!selectedBackend.requires_new&&!confirmNative||(!modelsDirty&&server?.state!=='error')}>{server?.state==='error'?'Retry setup':selectedBackend?.requires_new?'Start new conversation':'Apply models'}</button>{:else if settingsTab==='conversation'&&promptDirty}<button class="small-button" onclick={discardPrompt}>Discard changes</button><button class="small-button primary" onclick={choosePrompt} disabled={locked||confirmAction==='prompt'}>Apply prompt</button>{:else}<button class="small-button" onclick={closeSettings}>Done</button>{/if}</div>{/snippet}
 </Dialog>
 <Dialog open={transcriptOpen} title="Conversation" wide onclose={()=>{transcriptOpen=false;confirmAction=null}}>
  <div class="conversation-toolbar">{#if live||duplexActive}<button class="small-button" onclick={()=>duplexActive?stopDuplex():stopLive()}>Stop listening</button>{/if}<span>{turns.length?`${turns.length} exchanges`:'No messages yet'}</span><button class="small-button" onclick={newConversation} disabled={locked}>New conversation</button></div>
  {#if confirmAction==='new'}<div class="confirmation" role="alert"><h4>Start a new conversation?</h4><p>The current context will be cleared. Saved conversations are kept.</p><div class="button-row"><button class="small-button" onclick={()=>confirmAction=null}>Cancel</button><button class="small-button primary" onclick={()=>{confirmAction=null;void reset()}}>Start new</button></div></div>{/if}
  <div class="transcript" bind:this={transcriptBody} onscroll={()=>{followTranscript=transcriptBody.scrollHeight-transcriptBody.scrollTop-transcriptBody.clientHeight<80}} aria-live="polite">
   {#if !turns.length}<div class="empty-state"><h3>No messages yet</h3><p>Speak from the main screen or type a message below.</p></div>{/if}
   {#each turns as turn (turn.id)}<article class="exchange"><div class="message user-message"><strong>You</strong><p>{turn.input==='Voice message'?'Voice recording · no transcript available':turn.input}</p></div><div class="message"><strong>{server?.setup?.character||'Veyra'}</strong><p>{turn.reply||(turn.state==='running'?'Preparing your reply…':'No complete reply.')}</p>{#if turn.state==='error'||turn.state==='canceled'}<span class="field-note">{turn.state==='error'?'Incomplete reply':'Canceled'}</span>{/if}</div></article>{/each}
  </div>
  {#snippet footer()}{#if server?.capabilities.text_input}<form class="composer" onsubmit={e=>{e.preventDefault();void submit()}}><label class="sr-only" for="message">Message</label><textarea id="message" rows="2" placeholder="Write a message…" bind:value={draft} disabled={!available||recording||live} onkeydown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void submit()}}}></textarea><div class="composer-actions"><span class="field-note">Enter sends · Shift+Enter adds a line</span>{#if busy}<button type="button" class="small-button" onclick={cancel} disabled={canceling}>Stop response</button>{:else}<button type="submit" class="small-button primary" disabled={!available||recording||live||!draft.trim()}>Send</button>{/if}</div></form>{:else}<p class="field-note">This backend accepts voice from the main screen. Typed input is unavailable.</p>{/if}{/snippet}
 </Dialog>
</div>
